'use client';

/* ============================================================
 * HeroSlider = the sliding background used by EVERY hero on the site
 * (Home, the 4 service pages, About, Privacy Policy).
 *  - works with 1, 2, 3 or more pictures
 *  - the picture changes every SLIDE_SECONDS, the dots change it by hand
 *  - Arabic = slides move the other way (right to left)
 * You normally do NOT edit this file.
 * ============================================================ */
import { useCallback, useEffect, useState } from 'react';

export const SLIDE_SECONDS = 5; // time each picture stays

export function useHeroSlider(count: number) {
  /* cur = picture on screen, prev = picture that is sliding out (null at the start) */
  const [pos, setPos] = useState<{ cur: number; prev: number | null }>({ cur: 0, prev: null });

  const goTo = useCallback((i: number) => setPos((p) => (i === p.cur ? p : { cur: i, prev: p.cur })), []);

  /* One timer per picture: after a manual click the 5 seconds start again */
  useEffect(() => {
    if (count < 2) return;
    const t = setTimeout(() => setPos((p) => ({ cur: (p.cur + 1) % count, prev: p.cur })), SLIDE_SECONDS * 1000);
    return () => clearTimeout(t);
  }, [pos.cur, count]);

  return { pos, goTo };
}

export function HeroBackground({
  slides, cur, prev, isAr, overlay = 'bg-white/10',
}: {
  slides: string[]; cur: number; prev: number | null; isAr: boolean; overlay?: string;
}) {
  const dir = isAr ? -1 : 1;
  const MOVE = 'transform 1000ms ease-in-out'; // slide speed (1000 ms)

  /* Two steps for every change (works with 2, 3, 4... pictures):
     step 1 (prepare) = new picture is placed outside the screen, nothing moves;
     step 2 (go)      = 2 frames later new picture slides in, old one slides out.
     Plain CSS transition on inline style: no extra CSS file needed. */
  const [entered, setEntered] = useState(cur);
  useEffect(() => {
    let b = 0;
    const a = requestAnimationFrame(() => { b = requestAnimationFrame(() => setEntered(cur)); });
    return () => { cancelAnimationFrame(a); cancelAnimationFrame(b); };
  }, [cur]);
  const go = entered === cur;

  const styleOf = (i: number): React.CSSProperties => {
    if (i === cur) {
      if (prev === null) return { transform: 'translateX(0)', zIndex: 2 }; // first picture: no movement
      return go
        ? { transform: 'translateX(0)', transition: MOVE, zIndex: 2 } // arriving
        : { transform: `translateX(${100 * dir}%)`, transition: 'none', zIndex: 2 }; // waiting for the start
    }
    if (i === prev) {
      return go
        ? { transform: `translateX(${-100 * dir}%)`, transition: MOVE, zIndex: 1 } // leaving
        : { transform: 'translateX(0)', transition: 'none', zIndex: 1 }; // still on screen
    }
    return { transform: `translateX(${100 * dir}%)`, transition: 'none', zIndex: 0 }; // waiting outside the screen
  };

  return (
    <>
      <div className="absolute inset-0 overflow-hidden bg-[#faf8f5]" aria-hidden="true">
        {slides.map((slide, i) => (
          <div key={slide} className="absolute inset-0 w-full h-full will-change-transform" style={styleOf(i)}>
            {/* all pictures load at once, so a slide is never empty when it arrives */}
            <img src={slide} alt="" loading="eager" decoding="async" className="w-full h-full object-cover object-center" />
          </div>
        ))}
      </div>
      <div className={`absolute inset-0 ${overlay} z-[3] pointer-events-none`} />
    </>
  );
}

export function HeroDots({
  count, cur, onSelect, light = false,
}: {
  count: number; cur: number; onSelect: (i: number) => void; light?: boolean;
}) {
  if (count < 2) return null;
  return (
    <div className="flex items-center justify-center gap-1.5">
      {Array.from({ length: count }).map((_, idx) => (
        <button
          key={idx}
          onClick={() => onSelect(idx)}
          aria-label={`Slide ${idx + 1}`}
          className={`h-2 rounded-full transition-all duration-300 cursor-pointer ${
            idx === cur ? 'w-6 bg-[#d9a036]' : light ? 'w-2 bg-white/60' : 'w-2 bg-gray-400/60'
          }`}
        />
      ))}
    </div>
  );
}
